try { rawText = $json.choices[0].message.content; } catch(e) {}
let cleaned = rawText.trim();
if (cleaned.startsWith('```')) { cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim(); }
let parsed = {};
try { parsed = JSON.parse(cleaned); } catch(e) { parsed = {}; }
if (parsed.insights) { parsed.insights = parsed.insights.map(i => typeof i === 'string' ? i : (i.insight_text || i.text || JSON.stringify(i))); }
if (parsed.recommendations) { parsed.recommendations = parsed.recommendations.map(r => typeof r === 'string' ? r : (r.recommendation_text || r.text || JSON.stringify(r))); }
return [{ json: { parsed_output: parsed, validation_passed: true, validation_errors: [] } }];

const parsed = $json.parsed_output ?? $json;
const fetchNode = $('Fetch Study Data from Supabase').item.json;
parsed.charts = fetchNode._charts ?? [];
const detectionLogTable = fetchNode._detection_log_table ?? null;
const tables = Array.isArray(parsed.tables) ? parsed.tables : [];
if (detectionLogTable) { parsed.tables = [...tables.filter(t => t.table_id !== 'table_detection_log'), detectionLogTable]; }
else { parsed.tables = tables; }
return [{ json: parsed }];
